import { userGroupMembershipProjectionToValue } from './user-group-membership.model';
import { ComponentFixture, TestBed } from '@angular/core/testing';
import {
  InteractionMocks,
  RepositoryMock,
  allow,
  configureFeatureTesting,
  createWithoutTemplate,
  internals,
  mockRepository,
  mockTick,
  moduleCompiles,
} from 'app/shared/testing/feature-testing';

describe('userGroupMembershipProjectionToValue', () => {
  const value = {
    uid: 'value-uid',
    user: { $ref: 'ref-user' },
    resourceServer: { $ref: 'ref-resourceServer' },
    oauthClient: { $ref: 'ref-oauthClient' },
    groups: 'value-groups',
    version: 'value-version',
  } as any;

  it('returns null without projection', () => {
    expect(userGroupMembershipProjectionToValue(null)).toBeNull();
    expect(userGroupMembershipProjectionToValue(undefined)).toBeNull();
  });

  it('keeps a plain value', () => {
    expect(userGroupMembershipProjectionToValue(value)).toEqual(value);
  });

  it('reduces the projected references to their key', () => {
    const projection = {
      uid: 'value-uid',
      user: () => ({ uid: 'ref-user' }),
      resourceServer: () => ({ uid: 'ref-resourceServer' }),
      oauthClient: () => ({ uid: 'ref-oauthClient' }),
      groups: 'value-groups',
      version: 'value-version',
    } as any;
    expect(userGroupMembershipProjectionToValue(projection)).toEqual(value);
  });
});
